"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[47349],{63325(e){e.exports=JSON.parse('{"tag":{"label":"python","permalink":"/docs/tags/python","allTagsPath":"/docs/tags","count":16,"items":[{"id":"projects/professionnel/outils-internes","title":"Automatisation du quotidien : outils internes SONU","description":"Bots Slack, plan de charge, alertes ERP, suivi de l\'activit\xe9 GitHub et site de documentation interne. Outils d\xe9velopp\xe9s et d\xe9ploy\xe9s sur Kubernetes pour automatiser les t\xe2ches r\xe9p\xe9titives de l\'\xe9quipe SONU au CATIE.","permalink":"/docs/projects/professionnel/outils-internes"},{"id":"projects/personnel/body_analysis","title":"Body Analysis","description":"Application de suivi et d\'analyse corporelle (FastAPI, React, PostgreSQL, MinIO) : ingestion des exports Samsung Health, analytics d\'entra\xeenement (TRIMP, ACWR, d\xe9rive cardiaque), r\xe9cup\xe9ration et sommeil, galerie photo confidentielle.","permalink":"/docs/projects/personnel/body_analysis"},{"id":"projects/associatif/cameleon","title":"Cam\xe9l\xe9on","description":"Tableau de bord Flask et OpenCV pour enregistrer le flux d\'une cam\xe9ra IP et le diffuser dans l\'open space du fablab EirLab, lanc\xe9 depuis une simple cl\xe9 USB.","permalink":"/docs/projects/associatif/cameleon"},{"id":"projects/professionnel/cicd","title":"CI/CD - Workflows GitHub Actions mutualis\xe9s","description":"Biblioth\xe8que de workflows GitHub Actions r\xe9utilisables (g\xe9n\xe9rique, Python, ROS, Mbed, Zephyr) appel\xe9e par plusieurs dizaines de d\xe9p\xf4ts de l\'organisation CATIE, du test au d\xe9ploiement Helm ou Compose, document\xe9e et v\xe9rifi\xe9e contre son code.","permalink":"/docs/projects/professionnel/cicd"},{"id":"projects/personnel/colis-tracker","title":"Colis Tracker","description":"Suivi de colis Colissimo et Chronopost auto-h\xe9berg\xe9, sans cl\xe9 API ni service tiers : interrogation de l\'endpoint de suivi public de La Poste, import automatique des num\xe9ros depuis les mails d\'exp\xe9dition (IMAP), notifications ntfy.","permalink":"/docs/projects/personnel/colis-tracker"},{"id":"projects/personnel/dolibarr_project_dashboard","title":"Dolibarr Project Dashboard","description":"Tableau de bord FastAPI + React qui agr\xe8ge les donn\xe9es de plusieurs projets Dolibarr (t\xe2ches, temps pass\xe9, factures, opportunit\xe9s) pour le pilotage multi-projets, livr\xe9 en image Docker unique.","permalink":"/docs/projects/personnel/dolibarr_project_dashboard"},{"id":"projects/associatif/haricot-apringalle","title":"Haricot","description":"Bo\xeetier Raspberry Pi qui photographie la croissance d\'une plante \xe0 intervalle r\xe9gulier et g\xe9n\xe8re des timelapses depuis un tableau de bord web, projet d\'Antoine Pringalle \xe0 EirLab.","permalink":"/docs/projects/associatif/haricot-apringalle"},{"id":"projects/professionnel/inspection","title":"Inspection visuelle automatis\xe9e de v\xe9hicules","description":"Pipeline de vision par ordinateur embarqu\xe9 pour la d\xe9tection automatique de dommages sur v\xe9hicules neufs en parcs portuaires, jusqu\'\xe0 20 000 images en 3 secondes par v\xe9hicule. Traitement parall\xe9lis\xe9 des images brutes et inf\xe9rence sur NPU.","permalink":"/docs/projects/professionnel/inspection"},{"id":"projects/personnel/meeting-recorder","title":"Meeting Recorder","description":"Enregistreur de r\xe9unions enti\xe8rement local : capture deux pistes (micro et sortie son), transcription faster-whisper, synth\xe8se par un LLM local via Ollama, notes de r\xe9union fusionn\xe9es au compte rendu. Microservices Docker Compose, profils GPU 4 Go et CPU.","permalink":"/docs/projects/personnel/meeting-recorder"},{"id":"projects/associatif/reachy-mobile","title":"Reachy Mobile","description":"Rendre mobile le robot humano\xefde Reachy en l\'installant sur une base motoris\xe9e EZ Wheel : pilotage par interface web, d\xe9tection des visiteurs et partie de morpion, projet men\xe9 au fablab EirLab.","permalink":"/docs/projects/associatif/reachy-mobile"},{"id":"projects/personnel/recallarr","title":"Recallarr","description":"Journal personnel de ce qui a \xe9t\xe9 regard\xe9 dans Jellyfin, qui survit au nettoyage de la m\xe9diath\xe8que : synchronisation par webhook et r\xe9conciliation quotidienne, r\xe8gles de note et de favori, devenir de chaque titre, interface HTMX.","permalink":"/docs/projects/personnel/recallarr"},{"id":"projects/associatif/ronoco","title":"Ronoco","description":"Interface no-code pour programmer des robots ROS (manipulateurs MoveIt et robots roulants move_base) sans \xe9crire de code ; premier prototype d\xe9velopp\xe9 en stage de 2e ann\xe9e d\'\xe9cole d\'ing\xe9nieur.","permalink":"/docs/projects/associatif/ronoco"},{"id":"projects/professionnel/standards-python","title":"Standards Python - Template Cookiecutter","description":"Template Cookiecutter Python normalis\xe9 pour l\'organisation CATIE : trois types de projets (script, module, application), uv, Ruff, pre-commit, pytest, CI/CD GitHub Actions et synchronisation des projets par Cruft.","permalink":"/docs/projects/professionnel/standards-python"},{"id":"projects/personnel/task-horizon","title":"TaskHorizon","description":"Application Kanban FastAPI + React d\xe9ploy\xe9e sur AWS EKS via Terraform, avec un chart Helm multi-environnement et un pipeline CI/CD GitHub Actions du commit au cluster.","permalink":"/docs/projects/personnel/task-horizon"},{"id":"projects/associatif/vertical-plotter","title":"Vertical Plotter","description":"Traceur vertical qui dessine sur les tableaux blancs d\'EirLab, pilot\xe9 par Arduino, avec une cha\xeene de conversion SVG vers trajectoires adapt\xe9e aux 2 Ko de m\xe9moire du microcontr\xf4leur.","permalink":"/docs/projects/associatif/vertical-plotter"},{"id":"projects/associatif/wolf","title":"Wolf","description":"Application Flask de gestion interne d\'EirLab Community reliant les adh\xe9rents \xe0 Dolibarr : identification par carte, attribution des formations, gestion du stock par code-barres.","permalink":"/docs/projects/associatif/wolf"}],"unlisted":false}}')}}]);